-- Full catalog, part 5: supplier offers (APIMart, NezhaGate, PoYo; documentation and price lists read 22 Oct 2026).
--
-- 29 offers whose documented request covers a Genlixs model's settings exactly and whose documented price is below the KIE reference
-- for at least one setting (checked by supabase/catalog/build.mjs). All of them are created switched off: routing starts only when the owner
-- activates an offer in Providers ("Documented, not live-tested", every readiness check must pass) or verifies it with a live test. Customer
-- prices are unchanged: they follow the KIE reference under the global pricing policy, whichever supplier serves the job.
-- Also: the request builders of these offers, current prices of the NezhaGate GPT Image 2.5 offers (2K and 4K went up), and 34 research
-- entries of 18 Oct linked to their model with the reason they are not integrated. Duomi entries are left as they are.
-- Generated by supabase/catalog/build.mjs from supabase/catalog/offers.mjs. Repeatable: nothing that was configured is overwritten.

insert into app_private.provider_adapters (adapter, provider, description) values
  ('apimart-wan', 'apimart', 'APIMart Wan 2.6 / 2.6 Flash / 2.7 / 2.7-R2V / 2.7 video edit / 3.0 / 3.0 Prime (videos/generations)'),
  ('apimart-pixverse', 'apimart', 'APIMart PixVerse V6: text, image and multi-reference (videos/generations)'),
  ('apimart-happyhorse', 'apimart', 'APIMart HappyHorse 1.0: text, first frame, references and video edit (videos/generations)'),
  ('apimart-image-v2', 'apimart', 'APIMart Seedream 4.0 / 4.5 / 5.0 Pro, Qwen Image 3.0 / Pro and FLUX 3 Klein (images/generations)'),
  ('poyo-wan-2-7', 'poyo', 'PoYo Wan 2.7: text, image, reference and edit models (generate/submit)'),
  ('poyo-happyhorse', 'poyo', 'PoYo HappyHorse: text, image, reference and video edit (generate/submit)'),
  ('poyo-gemini-omni', 'poyo', 'PoYo Gemini Omni 1.1 Flash: text, first/last frame and reference images (generate/submit)')
on conflict (adapter) do nothing;

-- Same task API and documented result host as the supplier's existing integration.
update app_private.provider_adapters a set result_hosts = k.result_hosts
from app_private.provider_adapters k, (values ('apimart-wan', 'apimart-video'), ('apimart-pixverse', 'apimart-video'), ('apimart-happyhorse', 'apimart-video'), ('apimart-image-v2', 'apimart-video'), ('poyo-wan-2-7', 'poyo-kling-motion'), ('poyo-happyhorse', 'poyo-kling-motion'), ('poyo-gemini-omni', 'poyo-kling-motion')) as v(adapter, original)
where a.adapter = v.adapter and k.adapter = v.original and a.result_hosts = '{}';

